function updatePalette(q){paletteMatches=paletteItems().filter(i=>(i.label+' '+i.category).toLowerCase().includes(q.toLowerCase()));V.paletteIndex=Math.min(V.paletteIndex,Math.max(0,paletteMatches.length-1));$('#command-results').innerHTML=paletteMatches.map((i,n)=>vbtn(`${ic(i.category==='操作'?'right':'chat')}<span class="grow">${esc(i.label)}<small style="display:block;margin-top:4px">${esc(i.category)}</small></span>${i.key?`<kbd>${i.key}</kbd>`:''}`,'command-run',`data-i="${n}" role="option" aria-selected="${n===V.paletteIndex}"`,n===V.paletteIndex?'sel':'')).join('')||'<div class="empty">没有匹配项</div>';}
