submitMain=async function(text,annotations=S.annotations,opts={}){
 const targetId=opts.targetChat||V.chat;const t=S.threads.find(t=>t.id===targetId);if(!t){toast('目标对话不可用');return false;}if(V.pending.has(targetId)){toast('上一条正在提交');return false;}
 const captured=clone(annotations),marks=captured.map(a=>a.id+':'+a.rev);const draftStart=S.drafts.main||'';const refs=clone(getThreadData(targetId).contextRefs||[]);
 if(!text.trim()&&!captured.length&&!refs.length){toast('请输入内容或添加附件');return false;}
 saveThread();V.pending.add(targetId);toast('正在提交…');await new Promise(r=>setTimeout(r,350));
 if(V.failNext){V.failNext=false;V.pending.delete(targetId);toast('模拟发送失败，草稿与批注已保留');return false;}
 const d=targetId===V.chat?S:chatData[targetId];d.messages??=[];d.submitted??=[];d.annotations??=[];
 const m={id:uid('msg'),role:'user',text,annotations:captured,refs,time:vtime()};d.messages.push(m);d.submitted.push({id:uid('request'),messageId:m.id,text,annotations:captured,projectId:t.projectId,chatId:targetId,time:m.time});
 d.annotations=d.annotations.filter(a=>!marks.includes(a.id+':'+a.rev));d.contextRefs=(d.contextRefs||[]).filter(r=>!refs.some(x=>x.id?x.id===r.id:x.name===r.name));
 if(targetId===V.chat){if(S.drafts.main===draftStart)S.drafts.main='';S.formalCount++;}else if(d.draft===draftStart)d.draft='';
 d.messages.push({id:uid('receipt'),role:'system',text:'原型已接收 · 未调用模型',time:vtime()});t.updated=vtime();V.pending.delete(targetId);
 if(targetId===V.chat){saveThread();render();$('.messages')?.scrollTo(0,$('.messages').scrollHeight)}else toast('消息已提交到 '+t.title);
 return true;
};
