async function vAttach(files,scope='main'){const refs=[];for(const f of files){const id=uid('attach');filesMemory.set(id,f);refs.push({id,name:f.name,size:f.size,type:f.type})}if(scope==='main'){S.contextRefs??=[];S.contextRefs.push(...refs)}else{S.scopeRefs??={};S.scopeRefs[scope]??=[];S.scopeRefs[scope].push(...refs)}render();}
document.addEventListener('contextmenu',e=>{const obj=e.target.closest('[data-object]');if(obj){e.preventDefault();e.stopImmediatePropagation();objectMenu(obj.dataset.object,obj.dataset.objectId,null,{x:e.clientX,y:e.clientY});return;}const record=e.target.closest('[data-v="edit-record"],[data-v="open-log"]');if(record){e.preventDefault();e.stopImmediatePropagation();recordMenu(record.dataset.kind||'log',record.dataset.id,null,{x:e.clientX,y:e.clientY});return;}const file=e.target.closest('[data-action="open-file"],.artifact');if(file){e.preventDefault();e.stopImmediatePropagation();contextMenuForFile(file,{x:e.clientX,y:e.clientY});}},true);
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.record&&V.editor)V.editor.data[t.dataset.record]=t.value;if(t.id==='allchat-search'){V.search=t.value;$('#allchat-results').innerHTML=allChatsRows();$('#allchat-count').textContent=filteredThreads().length+' 个对话';}if(t.id==='command-query'){V.paletteIndex=0;updatePalette(t.value)}if(t.id==='find-chat-input'){V.findText=t.value;V.findIndex=0;findMatches(true)}},true);
document.addEventListener('change',e=>{if(e.target.dataset.record&&V.editor)V.editor.data[e.target.dataset.record]=e.target.value},true);
document.addEventListener('mouseover',e=>{const el=e.target.closest('[data-usage]');if(el&&!el.contains(e.relatedTarget))showUsage(el)},true);
document.addEventListener('mouseout',e=>{const el=e.target.closest('[data-usage]');if(el&&!el.contains(e.relatedTarget))$('#usage-pop')?.remove()},true);
document.addEventListener('focusin',e=>{if(e.target.matches('[data-usage]'))showUsage(e.target)},true);
document.addEventListener('focusout',e=>{if(e.target.matches('[data-usage]'))$('#usage-pop')?.remove()},true);
document.addEventListener('keydown',e=>{
 if(e.isComposing||e.keyCode===229)return;
 const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();
 const handled=()=>{e.preventDefault();e.stopImmediatePropagation()};
 if(e.key==='Escape'){if(V.menu){handled();const tr=V.menuTrigger;closeMenu();tr?.focus();return;}if(V.palette){handled();closePalette();return;}if(V.editor){handled();V.editor=null;$('#record-editor')?.remove();return;}if($('#modal')){handled();$('#modal').remove();return;}if(V.overview){handled();V.overview=false;$('#project-flyout')?.remove();return;}if(V.find){handled();V.find=false;render();return;}}
 if(V.menu&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){handled();const b=$$('button',V.menu);let i=b.indexOf(document.activeElement);i=e.key==='Home'?0:e.key==='End'?b.length-1:(i+(e.key==='ArrowDown'?1:-1)+b.length)%b.length;b[i]?.focus();return;}
 if(V.palette){if(['ArrowDown','ArrowUp'].includes(e.key)){handled();V.paletteIndex=(V.paletteIndex+(e.key==='ArrowDown'?1:-1)+paletteMatches.length)%Math.max(1,paletteMatches.length);updatePalette($('#command-query').value);$('.command-results .sel')?.scrollIntoView({block:'nearest'});return;}if(e.key==='Enter'){handled();const item=paletteMatches[V.paletteIndex];closePalette();item?.act();return;}}
 if(mod&&key==='k'){handled();if(e.shiftKey){go('projects');render()}else openPalette();return;}
 if(mod&&e.altKey&&key==='n'){handled();openDetached('quick');return;}
 if(mod&&!e.altKey&&key==='n'){handled();newThread();return;}
 if(mod&&key==='f'&&!['map','map-rich'].includes(route)){handled();V.find=true;if(!['work','free','ordered'].includes(route))go('work');render();$('#find-chat-input')?.focus();return;}
 if(e.altKey&&key==='s'){handled();V.overview=!V.overview;$('#project-flyout')?.remove();showFlyout();return;}
 if(e.target.id==='browser-address'&&e.key==='Enter'){handled();$('[data-v="browser-go"]')?.click();return;}
 if(e.target.dataset.draft&&e.target.dataset.draft!=='prompt'&&e.key==='Enter'&&!e.shiftKey){handled();$(`[data-v="send"][data-scope="${e.target.dataset.draft}"]`)?.click();return;}
 if((e.key==='Enter'||e.key===' ')&&e.target.matches('article[data-v]')){handled();e.target.click();return;}
 if(e.key==='F2'&&e.target.closest('[data-object]')){handled();const o=e.target.closest('[data-object]');objectMenu(o.dataset.object,o.dataset.objectId,o);$('[data-v="rename-object"]')?.click();}
},true);
document.addEventListener('dragover',e=>{const z=e.target.closest('[data-vdrop]');if(z){e.preventDefault();e.stopImmediatePropagation();z.classList.add('dragover')}},true);
document.addEventListener('dragleave',e=>e.target.closest('[data-vdrop]')?.classList.remove('dragover'),true);
document.addEventListener('drop',e=>{const z=e.target.closest('[data-vdrop]');if(z){e.preventDefault();e.stopImmediatePropagation();z.classList.remove('dragover');if(z.dataset.vdrop==='record')appendRecordFiles([...e.dataTransfer.files]);else vAttach([...e.dataTransfer.files],z.dataset.scope||'main')}},true);
document.addEventListener('paste',e=>{const c=e.target.closest('[data-composer]');if(c&&e.clipboardData?.files.length){e.preventDefault();e.stopImmediatePropagation();vAttach([...e.clipboardData.files],c.dataset.composer)}},true);
window.addEventListener('hashchange',render);
