window.SSV2={state:()=>V,selectProject,loadThread,newThread,allMessages,appendRecordFiles,recordEditor,saveRecord,deleteRecord,
 togglePin,openDetached,goMessage,addRef:r=>{S.contextRefs??=[];S.contextRefs.push({...r,id:uid('ref')});render()},
 failNext:()=>{V.failNext=true},copyValue:()=>V.copied,submit:(text,marks)=>submitMain(text,marks),
 menu:(kind,id)=>objectMenu(kind,id,null,{x:200,y:180}),palette:openPalette};
window.SS={...window.SS,getState:()=>S,navigate:go,render,submitMain,reset:()=>{S=initial();vInit();V.chat='e-theory';V.panel=null;V.overview=false;render()}};
// Scope map synchronization to this prototype's project. Existing editor Save can keep its action.
receiveMap=function(payload){if(payload.projectId&&payload.projectId!==S.projectId){const bucket=projectBuckets[payload.projectId];if(bucket){bucket.nodes=clone(payload.nodes);bucket.collapsed=clone(payload.collapsed||{});bucket.mapHistory=clone(payload.mapHistory||[])}return;}S.nodes=clone(payload.nodes);S.collapsed=clone(payload.collapsed||{});S.mapHistory=clone(payload.mapHistory||S.mapHistory);if(['workbench','map','map-rich','map-history'].includes(route))render();};
window.SS.receiveMap=receiveMap;
try{window.mapChannel?.close();window.mapChannel=new BroadcastChannel('sciencescope-design-map-'+S.projectId);window.mapChannel.onmessage=e=>receiveMap(e.data)}catch{}
